'use strict';
(() => {
 const R=window.OBSERVATORY_RESEARCH;
 const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const fmt=x=>Number.isFinite(Number(x))?Number(x).toPrecision(5).replace(/\.?0+(?=e|$)/,''):String(x);
 const routes=[['home','Overview'],['results','Computed fields'],['response','Response test'],['demonstrations','Calculators'],['evidence','Four frontiers'],['experiments','Experiment plan'],['advisor','Advisor protocol'],['sources','Sources']];
 let technical=false,metric='x',responseCase='',responseMetric='u',sourceQuery='',sourceCategory='',sourcePage=1,lastOpener=null;
 try{technical=localStorage.getItem('observatory-explanation-mode')==='technical'}catch{}
 const tag=(s,type='')=>'<span class="research-status '+type+'">'+escape(s)+'</span>';
 const explain=(plain,deep)=>'<p>'+escape(technical?deep:plain)+'</p>';
 const links=ids=>ids.map(id=>{const s=R?.sources.find(v=>v.id===id);return s?'<a href="'+escape(s.url)+'" target="_blank" rel="noopener noreferrer">'+escape(s.title)+'</a>':''}).filter(Boolean).join(' · ');
 const table=(head,rows)=>'<div class="research-scroll"><table class="research-table"><thead><tr>'+head.map(s=>'<th scope="col">'+escape(s)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(x=>'<td>'+escape(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
 const head=(title,plain,deep)=>'<div class="research-head"><div><div class="research-tag">Quantum fields · Gravitation · Reproducible research</div><h1>'+escape(title)+'</h1>'+explain(plain,deep)+'</div><div class="research-mode" role="group" aria-label="Explanation depth"><button data-r-mode="plain" aria-pressed="'+!technical+'">Plain language</button><button data-r-mode="technical" aria-pressed="'+technical+'">Technical</button></div></div>';
 function chart(series,{title='',xLabel='Time s = mₑt',yLabel='',sourceOff=null,zero=true}={}){
  const clean=series.map(s=>({...s,points:s.points.filter(p=>p.length===2&&p.every(Number.isFinite))}));const pts=clean.flatMap(s=>s.points);
  if(!pts.length)return '<p class="research-error" role="status">No finite data are available for this plot.</p>';
  let xmin=Math.min(...pts.map(p=>p[0])),xmax=Math.max(...pts.map(p=>p[0])),ymin=Math.min(...pts.map(p=>p[1])),ymax=Math.max(...pts.map(p=>p[1]));
  if(zero){ymin=Math.min(0,ymin);ymax=Math.max(0,ymax)}if(xmin===xmax){xmin-=.5;xmax+=.5}if(ymin===ymax){const pad=Math.max(1e-9,Math.abs(ymin)*.1);ymin-=pad;ymax+=pad}
  const pad=(ymax-ymin)*.08;ymin-=pad;ymax+=pad;const sx=x=>85+(x-xmin)/(xmax-xmin)*585,sy=y=>268-(y-ymin)/(ymax-ymin)*225;
  let svg='<svg class="research-svg" role="img" aria-label="'+escape(title+'. '+xLabel+'. '+yLabel)+'" viewBox="0 0 710 335"><title>'+escape(title)+'</title>';
  for(let i=0;i<=4;i++){let x=xmin+(xmax-xmin)*i/4,y=ymin+(ymax-ymin)*i/4;svg+='<path d="M85 '+sy(y)+'H670" stroke="#e4eaf0"/><text x="75" y="'+(sy(y)+5)+'" text-anchor="end">'+escape(fmt(y))+'</text><text x="'+sx(x)+'" y="290" text-anchor="middle">'+escape(fmt(x))+'</text>'}
  if(sourceOff!==null&&sourceOff>=xmin&&sourceOff<=xmax)svg+='<path d="M'+sx(sourceOff)+' 32V268" stroke="#887454" stroke-dasharray="4 5"/><text x="'+(sx(sourceOff)+8)+'" y="28">Source stops</text>';
  svg+='<path d="M85 35V268H670" fill="none" stroke="#687e93"/>';
  const colors=['#175db4','#b16a16','#23785e','#814e8e'];
  clean.forEach((s,i)=>{svg+='<polyline fill="none" stroke="'+(s.color||colors[i%4])+'" stroke-width="2.5" points="'+s.points.map(p=>sx(p[0]).toFixed(2)+','+sy(p[1]).toFixed(2)).join(' ')+'"/>'});
  svg+='<text x="377" y="324" text-anchor="middle">'+escape(xLabel)+'</text><text x="17" y="155" text-anchor="middle" transform="rotate(-90 17 155)">'+escape(yLabel)+'</text></svg>';
  return '<figure class="research-chart" tabindex="0" aria-label="Scientific plot; scroll horizontally on narrow screens"><figcaption>'+escape(title)+'</figcaption>'+svg+'<div class="research-legend">'+clean.map((s,i)=>'<span><i style="background:'+(s.color||colors[i%4])+'"></i>'+escape(s.name)+'</span>').join('')+'</div></figure>';
 }
 function baselineSeries(key='x'){
  const m=R.baseline.macro;const ys=key==='current'?R.baseline.full_current:key==='energy'?m.Wexact:key==='residual'?m.energy_work_residual:m[key];
  return m.s.map((t,i)=>[t,ys[i]]);
 }
 function baselineChart(key='x'){
  const names={x:['Electric field','E / E꜀'],current:['Full matter current','j / (e mₑ³)'],a:['Vector potential','e A / mₑ'],energy:['Energy and supplied work','e²ρ / mₑ⁴'],residual:['Energy minus source work','Energy residual']};let n=names[key]||names.x;
  const series=[{name:n[0],points:baselineSeries(key)}];if(key==='energy')series.push({name:'Integrated source work',points:R.baseline.macro.s.map((s,i)=>[s,R.baseline.macro.Wdrive[i]])});
  return chart(series,{title:n[0]+' · recorded computation',yLabel:n[1],sourceOff:4});
 }
 const fronts=[
  {id:'wgc',name:'Weak gravity & Festina Lente',question:'Which charged particles can coexist with a slowly expanding universe?',simple:'Spectrum bounds and charged black-hole discharge depend on particle masses, charges and the geometry. Our flat-space pulse does not test these conjectures.',technical:'Use canonically normalized charge, scalar forces and the correct RN–dS quantum state. Algebraic overlap of electric WGC and FL mass windows is not a causal mass/charge evolution.',equation:'m² ≤ 2g²n²Mₚ²;   m⁴ ≳ 6g²n²Mₚ²H²',gap:'Horizon-regular current and stress; shell energy; coupled mass/charge evolution.',test:'Compare causal charge and energy fluxes in one fixed de Sitter horizon geometry before changing its spectrum.',sources:['G01','G02','G04','P3-R08']},
  {id:'schwinger',name:'Strong fields & curved-space pair creation',question:'How does quantum matter push back on the fields that create it?',simple:'An electric field changes the quantum state, which creates a current and changes the field again. Curvature also changes the modes; the metric needs their full stress.',technical:'The recorded finite-regulator Maxwell–Dirac closure includes coherent polarization and on-shell magnetic matching. Covariantly renormalized anisotropic pressures are not yet supplied.',equation:'∇F = J;   Gμν + Λgμν = κ〈Tμν〉ren',gap:'Common curved-space current, energy and both directional pressures; state and fluctuation control.',test:'Check the new tangent response independently, then derive and implement common directional-stress subtraction.',sources:['C01','C02','N02','H04','P3-R01','P3-R07']},
  {id:'cauchy',name:'Mass inflation & the inner horizon',question:'What happens where counterstreaming black-hole fluxes are blueshifted?',simple:'Classical inner horizons can become singular. Quantum stress may change that evolution, but violating a classical energy condition does not prove a smooth endpoint.',technical:'Specify characteristic double-null data, null stress and charge fluxes, reduced dilaton/backscatter terms and the regularity class of extension. Bianchi-I has no Cauchy horizon.',equation:'1 − 2Gm/r + GQ²/(4πr²) − Λr²/3 = −4rᵤrᵥ/Ω²',gap:'State-dependent null fluxes and a validated horizon-regular evolution.',test:'Refine both characteristic constraints and renormalized stress before interpreting an apparent bounce.',sources:['G03','H09','H10','P3-R09']},
  {id:'mixing',name:'Photon–graviton conversion',question:'Does quantum dispersion preserve or suppress wave conversion?',simple:'Two coupled waves can exchange energy when their phases stay aligned. Magnetic vacuum dispersion can spoil that alignment; geometry and absorption also matter.',technical:'Match transverse polarization eigenmodes, energy-flux normalization and the mixed vertex at the same loop order. Parallel static susceptibility alone is not a photon refractive index.',equation:'P = 4μ²/(δ²+4μ²) · sin²[L√(δ²+4μ²)/2]',gap:'Full momentum-dependent polarization and mixed kernel along a specified ray.',test:'Reproduce the constant lossless limit before testing a varying field, plasma crossing and absorption.',sources:['G13','N03','P3-R10','P3-R11']}
 ];
 function home(){return head('Quantum fields & gravity','Explore how a quantum current changes an electric field. Follow the evidence toward a calculation in evolving spacetime.','Study a causal Maxwell–Dirac mean field, finite-regulator convergence and tangent response, then the missing covariant stress and Einstein constraint closure.')+
  '<div class="research-grid"><section class="research-panel">'+tag('Recorded computation','verified')+'<h2>The field changes after its source stops</h2>'+baselineChart()+
  '<div class="research-metrics"><div><strong>−0.03757</strong><span>Electric field at s = 50</span></div><div><strong>3.26 × 10⁻⁹</strong><span>Field change under final grid refinement</span></div><div><strong>Still open</strong><span>Full Einstein–QED feedback</span></div></div><div class="research-actions"><a class="research-primary" href="#research/results">Inspect the recorded result</a><button data-r-info="baseline">Model & evidence</button></div></section>'+
  '<aside class="research-panel"><h2>Read the feedback loop</h2>'+explain('The source first supplies energy. Quantum matter responds with a current. That current changes the electric field—even after the source switches off.','The pump F(s) prepares the state. Dirac modes determine Jren; Maxwell evolves x′ = F − e²Jren. The magnetic background is static, and no metric is evolved.')+
  '<ol><li><strong>Understand.</strong> Switch explanation depth at any time.</li><li><strong>Inspect.</strong> Open a plot, its data and separate error checks.</li><li><strong>Challenge.</strong> Choose a hypothesis and a test that could reject it.</li></ol><p class="research-note">A checked reduced model is a step toward the research problem. It does not establish the full continuum theory or a solved spacetime.</p><div class="research-actions"><a href="#research/response">Explore the new response test</a></div></aside></div>'+
  '<section class="research-panel"><h2>Four connected questions</h2><div class="research-flow">'+fronts.map(f=>'<div><b>'+escape(f.name)+'</b><span>'+escape(f.question)+'</span><p><button class="research-button" data-r-front="'+f.id+'">View open dependencies</button></p></div>').join('')+'</div></section>'+
  '<section class="research-next"><h2>How to use each feature</h2><div class="research-features">'+[
   ['Computed fields','Change the plotted observable, inspect the finite-grid metadata and download its exact saved CSV.','results'],
   ['Response test','See whether a small source change agrees with the derivative predicted by the coupled equations.','response'],
   ['Calculators','Change phase mismatch, field strengths or photon counts in clearly labeled analytic models.','demonstrations'],
   ['Four frontiers','Open assumptions, central equations and the next discriminating test for every original problem.','evidence'],
   ['Experiment plan','Follow dependencies, read rejection gates and record a browser-local research note.','experiments'],
   ['Advisor protocol','Read the roles, evidence gates and stop rules; download the reusable advisor guide.','advisor'],
   ['Source ledger','Search papers, government records, patents and methodology. Inspect reading depth and versions.','sources'],
   ['Learning rooms','Use Study, Explore and Laboratory above for mathematics, physics foundations, histories and existing tools.','study']
  ].map(([t,d,r])=>'<article class="research-feature"><h3>'+t+'</h3><p>'+d+'</p><a href="'+(r==='study'?'#study':'#research/'+r)+'">Open '+t.toLowerCase()+' →</a></article>').join('')+'</div></section>';
 }
 function results(){const b=R.baseline;return head('Inspect the computed fields','Every curve here comes from a saved numerical run. Changing the view does not rerun the solver.','Recorded DOP853 integration at b = 10, levels 0–8, canonical window ±40 and 4096 Gauss–Legendre nodes per level; 251 output times.')+
  '<section class="research-panel"><div class="research-control"><label for="r-metric">Observable<select id="r-metric">'+[['x','Electric field'],['current','Full matter current'],['a','Vector potential'],['energy','Energy / source work'],['residual','Energy residual']].map(([k,v])=>'<option value="'+k+'" '+(metric===k?'selected':'')+'>'+v+'</option>').join('')+'</select></label></div><div id="r-main-chart">'+baselineChart(metric)+'</div><p class="research-small">Saved points are joined by lines. A sampled peak is not an exact continuous-time extremum. The source stops at s = 4.</p><div class="research-actions"><button data-r-download="baseline">Download plotted CSV</button><button data-r-info="baseline">Parameters & meaning</button></div><details><summary>Exact plotted data</summary><div id="r-data-table">'+metricTable()+'</div></details></section>'+
  '<section class="research-panel"><h2>Separate the error questions</h2>'+explain('The initial curve conserved energy very closely but had an inaccurate momentum integral. The advisor required another grid refinement before accepting the late-time field.','Finite-grid Ward identities hold before the continuum limit. Momentum quadrature, longitudinal window, Landau truncation and ODE tolerances are distinct controls; none is a statistical confidence interval.')+
  table(['Comparison','Observed change','Meaning'],[['2048 → 4096 momentum nodes','3.257 × 10⁻⁹','Maximum sampled field-history difference'],['Full matter current, same refinement','1.1315 × 10⁻⁶','j / (e m³), not just the Maxwell numerator'],['Levels through 8 → through 12','5.061 × 10⁻⁸','Endpoint shift, separate Landau check'],['K40 / 2048 → K60 / 3072','4.107 × 10⁻¹¹','Window comparison at similar spacing'],['Energy / source work','1.18 × 10⁻¹¹ relative','Finite-model conservation; not total error']])+
  '<p class="research-note">The earlier 1024 → 2048-node shift was 1.115 × 10⁻⁵. Conservation did not reveal that error. The strict 10⁻¹⁸ benchmark target also failed; it remains documented.</p><details><summary>All retained long-time grid results</summary>'+table(['Case','Nodes','Highest level','Final E / E꜀'],R.convergence.rows.map(r=>[r.case,r.nK,r.ncut,r.final_x]))+'</details></section>'+
  '<section class="research-panel"><h2>Does the vacuum response survive subtraction?</h2>'+explain('Removing a divergent contribution can also remove a real finite response. A weak source reveals whether the physical magnetic response was restored once.','At b = 100 the static linear comparator is x_target /(1+χB). The late mean uses s = 35.1–40, the final 50 of 401 points; finite-frequency transients remain.')+
  table(['Prescription','Late mean electric field','Interpretation'],R.weak.rows.map(r=>[r.mode,fmt(r.late_mean_x),r.mode==='matched'?'Physical finite matching':'Deliberately different prescription']))+'<p>Static matched prediction: <strong>'+fmt(R.weak.expected_linear_matched)+'</strong>.</p><div class="research-actions"><button data-r-info="matching">Read the matching argument</button></div></section>';
 }
 function metricTable(){const ys=baselineSeries(metric);return table(['s = mₑt',metric==='current'?'j / (e mₑ³)':metric],ys.map(p=>p.map(String)))}
 function response(){return head('Challenge the response','A small change in the source gives a new test of the coupled equations. Agreement checks the computed derivative, not the validity of every quantum approximation.','Compare the tangent Maxwell–Dirac system with independent spinor finite perturbations at fixed regulator. Use norms that remain finite when the background field crosses zero.')+
  '<section class="research-panel">'+(R.response?tag('Checked finite model','verified')+'<h2>The source changes; the field responds</h2><div id="r-response-view">'+responseContent()+'</div>':'<h2>Response experiment</h2><p>The baseline results are available. No new response dataset is included in this snapshot.</p>')+
  '<p class="research-note">A tangent sensitivity is not the complete quantum current-noise or stress-fluctuation test. It does not by itself establish semiclassical validity.</p><div class="research-actions"><button data-r-doc="response_contract.md">Open the equation contract</button><button data-r-download="response">Download response records</button></div></section>'+
  '<section class="research-panel"><h2>What could falsify it?</h2><ol><li>Centered source perturbations disagree with the tangent after time and momentum refinement.</li><li>Gauge-equivalent changes alter the physical response.</li><li>The differentiated energy/work identity fails.</li><li>A deliberately incomplete tangent equation passes the same evaluator.</li></ol><p class="research-small">Physics interpretation: '+links(['H02','V02'])+'</p></section>';
 }
 function responseRecord(){const keys=Object.keys(R.response?.records||{});if(!keys.includes(responseCase))responseCase=R.physics_acceptance?.selected_production_key||R.physics_acceptance?.selected_record||keys.find(k=>k==='production_nk1024_baseline')||keys[0];return R.response?.records[responseCase]}
 function responsePlot(){const rec=responseRecord(),m=rec?.base?.macro;if(!m?.s)return '<p>No recorded response array is available.</p>';const key=responseMetric,labels={u:['Electric-field sensitivity','δ(E / E꜀)'],deltaJmatter_direct:['Direct matter-current sensitivity','δj / (e mₑ³)'],delta_energy_work_residual:['Differentiated energy/work residual','δW − integrated δ(source work)']};const n=labels[key]||labels.u;return chart([{name:n[0],points:m.s.map((t,i)=>[t,m[key]?.[i]])}],{title:n[0]+' · '+responseCase,yLabel:n[1]})}
 function responseContent(){const r=R.response;if(!r)return '';const rec=responseRecord(),m=rec?.base?.macro,params=rec?.parameters||{};
  const compare=R.response_comparison,verify=R.response_verification,ref=r.targeted_refinement||{};
  const convergence=Object.entries(r.fixed_grid_convergence||{}).filter(([k,v])=>v&&typeof v==='object'&&Number.isFinite(v.u)).map(([k,v])=>[k.replaceAll('production_nk','').replaceAll('_baseline','').replace('_to_',' → '),fmt(v.u),fmt(v.deltaJmatter)]);
  for(const [k,v] of Object.entries(ref))if(v&&Number.isFinite(v.max_abs_u_difference))convergence.push([k.replaceAll('production_nk','').replaceAll('_baseline','').replace('_to_',' → '),fmt(v.max_abs_u_difference),fmt(v.max_abs_deltaJmatter_difference)]);
  return (responseCase===R.physics_acceptance?.selected_record?tag('Advisor-selected finite response','verified'):['production_nk128','production_nk256'].includes(responseCase)?tag('Retained coarse grid · refinement failed','failed'):tag('Comparison case · inspect its regulator'))+'<p>The source-amplitude tangent asks how the entire field history changes when the preparation amplitude changes. It is normalized by the amplitude parameter, so zero crossings do not create artificial divergences.</p><div class="research-control"><label>Recorded case<select id="r-response-case">'+Object.keys(r.records).map(k=>'<option value="'+escape(k)+'" '+(k===responseCase?'selected':'')+'>'+escape(k.replaceAll('_',' '))+'</option>').join('')+'</select></label><label>Response observable<select id="r-response-metric">'+[['u','Electric-field sensitivity'],['deltaJmatter_direct','Direct matter current'],['delta_energy_work_residual','Tangent energy residual']].map(([k,v])=>'<option value="'+k+'" '+(k===responseMetric?'selected':'')+'>'+v+'</option>').join('')+'</select></label></div><div id="r-response-chart">'+responsePlot()+'</div><p class="research-small">This case: b = '+escape(params.b)+', levels 0–'+escape(params.ncut)+', momentum window ±'+escape(params.Kmax)+', '+escape(params.nK)+' nodes per level. The delayed-probe case varies a separate pulse beginning at s = 8. Other cases vary the original source amplitude.</p><div class="research-actions"><button data-r-download="response-csv">Download this plotted CSV</button><button data-r-doc="response_advisor_review.md">Read the acceptance decision</button></div><details><summary>Saved response values</summary><div id="r-response-table">'+responseTable()+'</div></details><h3>Two different questions, two checks</h3>'+table(['Check','Result','What it establishes'],[['Independent spinor/finite-difference controls',verify?.all_checks_passed?'13 / 13 pass':'Inspect verification record','Finite-model derivative, gauge and causal support'],['Production comparison and provenance',compare?.all_checks_passed?'19 / 19 pass':'Inspect comparison record','Two small configurations, separate complex implementation'],['512 → 1024 momentum nodes',convergence.at(-1)?.[1]||'Unavailable','Only this fixed window, Landau cutoff and time interval']])+
  (compare?.cases?table(['Independent comparison','Max field-tangent difference','Max direct-current difference'],Object.entries(compare.cases).map(([k,v])=>[k,fmt(v.maximum_full_history_absolute_differences.u),fmt(v.maximum_full_history_absolute_differences.deltaJmatter_direct)])):'')+
  '<h3>Refinement exposed a hidden numerical error</h3>'+table(['Momentum nodes','Max change in field sensitivity','Max change in current sensitivity'],convergence)+'<p class="research-note">Early field sensitivities changed by 0.0504 and 0.0130 despite good conservation. The final fixed-window refinement resolves this quadrature test. The response has not yet passed an independent momentum-window or Landau-cutoff removal, quantum-noise test or metric evolution.</p>';
 }
 function responseTable(){const m=responseRecord()?.base?.macro;if(!m)return '';return table(['s = mₑt',responseMetric],m.s.map((t,i)=>[String(t),String(m[responseMetric]?.[i])]))}

 function finite(v,name,min,max){if(String(v).trim()==='')throw Error(name+' is required.');const n=Number(v);if(!Number.isFinite(n)||n<min||n>max)throw Error(name+' must be a finite number from '+min+' to '+max+'.');return n}
 function mixing(u,v){u=finite(u,'Mixing μL',0,100);v=finite(v,'Mismatch δL',-1000,1000);const z=Math.hypot(u,v/2),sinc=Math.abs(z)<1e-5?1-z*z/6+z**4/120:Math.sin(z)/z;return u*u*sinc*sinc}
 function budget(x,b){x=finite(x,'Electric strength',-1e22,1e22);b=finite(b,'Magnetic strength',0,1e22);return 2.4008495742608602e-39*(x*x+b*b)/10001}
 function detector(ns,nlo){ns=finite(ns,'Signal photons',0,1e12);nlo=finite(nlo,'Local-oscillator photons',0,1e16);return ns+nlo===0?0:2*Math.sqrt(ns)*Math.sqrt(nlo)/Math.sqrt(ns+nlo)}
 function demonstrations(){return head('Calculate a physical limit','These small models run in your browser. They illustrate an equation and its limits; they do not simulate a black hole or rerun the quantum-field calculation.','Dimensionless constant two-mode mixing, an electron-scale Einstein source budget and an ideal coherent balanced-detector SNR. Every input is domain checked.')+
  '<section class="research-panel">'+tag('Analytic demonstration')+'<h2>Coherence and phase mismatch</h2>'+explain('As coupled waves drift out of phase, conversion becomes less efficient. Move the mismatch to see the change.','For u = μL and v = δL, P = u² sinc²(√(u²+v²/4)). Constant lossless two-mode coefficients; no plasma, absorption or QED mixed vertex is calculated.')+
  '<div class="research-control"><label>Mixing μL<input id="r-mix-u" type="number" min="0" max="100" step="0.1" value="1"></label><label>Mismatch δL<input id="r-mix-v" type="number" min="-1000" max="1000" step="0.5" value="0"></label><button class="research-button" data-r-calc="mix">Calculate conversion</button></div><div id="r-mix-result" aria-live="polite"></div><div class="research-actions"><button data-r-front="mixing">Assumptions & open physics</button></div></section>'+
  '<div class="research-split"><section class="research-panel">'+tag('Source-budget estimate')+'<h2>Can these fields source this curvature?</h2>'+explain('A very strong laboratory field can still have a tiny gravitational effect. This checks the electromagnetic energy scale in electron units.','Compute κρEM/mₑ² = [4πGmₑ²/e²](x²+b²). Maxwell stress is traceless, so this is not the Ricci scalar R/mₑ².')+
  '<div class="research-control"><label>Electric E / E꜀<input id="r-budget-x" type="number" value="1" step="1"></label><label>Magnetic B / B꜀<input id="r-budget-b" type="number" value="100" min="0" step="10"></label><button class="research-button" data-r-calc="budget">Estimate source scale</button></div><div id="r-budget-result" aria-live="polite"></div><p class="research-small">At fields beyond the model regime this is an algebraic scale estimate only. It does not construct a physical supporting object.</p></section>'+
  '<section class="research-panel">'+tag('Ideal detector model')+'<h2>Amplification is not noiseless</h2>'+explain('A stronger reference beam amplifies the measured signal and its fluctuations. At fixed signal, their ratio approaches a finite limit.','For ideal balanced coherent detection at optimal phase, SNR = 2√(Ns NLO)/√(Ns+NLO), approaching 2√Ns. Squeezing, losses and actual detector geometry require different models.')+
  '<div class="research-control"><label>Signal photons Nₛ<input id="r-det-ns" type="number" min="0" value="2" step="1"></label><label>Reference photons NLO<input id="r-det-lo" type="number" min="0" value="2000" step="100"></label><button class="research-button" data-r-calc="detector">Calculate SNR</button></div><div id="r-det-result" aria-live="polite"></div><div class="research-actions"><button data-r-info="claims">Evidence behind unusual claims</button></div></section></div>';
 }
 function evidence(){return head('Four frontiers, explicit dependencies','Open each question to see which part has been checked and what still prevents a complete solution.','Geometry, initial quantum state, renormalization prescription and observable must agree before partial models can be combined.')+
  fronts.map(f=>'<section class="research-panel">'+tag('Open research problem','open')+'<h2>'+escape(f.name)+'</h2>'+explain(f.simple,f.technical)+'<div class="research-eq">'+escape(f.equation)+'</div><p><strong>Missing:</strong> '+escape(f.gap)+'</p><p><strong>Next falsifiable test:</strong> '+escape(f.test)+'</p><div class="research-actions"><button data-r-front="'+f.id+'">Inspect assumptions & sources</button><a href="#research/experiments">Follow the experiment plan</a></div></section>').join('')+
  '<section class="research-panel"><h2>Correction register</h2><p>Each correction states what was observed, what changed and what it does not establish. The full advisor review also checks a displayed equation against a later reduction in a recent screening paper.</p><button data-r-doc="response_advisor_review.md">Read the detailed audit</button>'+R.errata.map(e=>'<article class="research-finding">'+tag('Documented correction','failed')+'<h3>'+escape(e.title)+'</h3><p>'+escape(e.detail)+'</p></article>').join('')+'</section>';
 }
 const experiments=[
 ['P3','Coupled response','Executed model test','Tangent response versus centered source perturbations and independent spinors.','Reject the numerical derivative if discrepancy does not fall with perturbation size/refinement, or if gauge/energy controls fail.','Round-3 matched current; fixed state and regulator.'],
 ['P3b','Response spectrum and state families','Open','Reconstruct the response with independent probes and physical initial-state variations.','Reject a spectrum inferred from one source history or a spurious field-zero ratio.','P3; a fixed regulator and independently prepared perturbations.'],
 ['P3c','Connected quantum noise','Open','Evaluate the retarded current commutator and fluctuations for the same quantum state.','A classical tangent sensitivity alone cannot satisfy this gate. Bound fluctuations relative to a nonsingular background scale.','P3 plus a genuine quantum correlation calculation.'],
 ['P4','Covariant directional stresses','Open','Derive current, energy and both pressures from the same anisotropic state and counterterms.','Reject an energy-only closure or a nonconvergent Ward residual.','Flat matched limit, anisotropic mode connection, common renormalization.'],
 ['P5','Metric feedback','Open','Evolve the Bianchi-I Einstein equations with the verified quantum stress.','Hamiltonian constraint and stress Ward identity must converge together.','P4 and an explicitly supported initial gravitational state.'],
 ['P6','Strong curvature & field support','Open','Construct consistent initial data and track curvature/derivative control.','Reject electron-scale curvature attributed to insufficient electromagnetic stress.','P5; additional gravitating sources where required.'],
 ['P7','Matched wave conversion','Open','Compute transverse modes, mixed vertex and a flux-normalized ray transfer system.','Reject mismatch-only predictions that omit physical polarizations, geometry or damping.','Independent classical limit and a common quantum matching prescription.'],
 ['P8','Charged horizons','Open','Use geometry-matched quantum fluxes in mass/charge and double-null evolution.','Require horizon regularity, state specification, constraint refinement and a defined extension criterion.','P4; separate de Sitter and Cauchy-horizon state/geometry contracts.']
 ];
 function plan(){let note='';try{note=localStorage.getItem('observatory-research-note')||''}catch{}return head('Plan the next discriminating experiment','The goal is a complete coupled solution. Each step must earn the assumptions needed by the next one.','A dependency-ordered research programme, not a claim of guaranteed solvability. Failure can revise a hypothesis; a change of model creates a new contract and benchmark set.')+
  '<section class="research-panel"><h2>From checked response to evolving spacetime</h2><p><button data-r-doc="physics_completion_roadmap.md">Open the detailed four-branch research plan</button></p>'+table(['Stage','Work package','Status'],experiments.map(e=>[e[0],e[1],e[2]]))+'<p class="research-small">P7 and the horizon work are distinct geometries, not extra terms to paste into a homogeneous solution.</p></section>'+
  experiments.map(e=>'<section class="research-panel">'+tag(e[2],e[2]==='Open'?'open':'verified')+'<h2>'+e[0]+' · '+escape(e[1])+'</h2><p>'+escape(e[3])+'</p><p><strong>Rejection gate:</strong> '+escape(e[4])+'</p><p class="research-small"><strong>Dependencies:</strong> '+escape(e[5])+'</p></section>').join('')+
  '<section class="research-panel"><h2>Your next hypothesis</h2><p>Write the prediction, null comparison, observable and rejection threshold before interpreting a result.</p><label for="r-note">Research note · saved only in this browser</label><textarea id="r-note" class="research-notes" maxlength="30000" placeholder="Hypothesis → assumptions → experiment → rejection rule → evidence">'+escape(note)+'</textarea><div class="research-actions"><button data-r-save-note>Save note</button><button data-r-download="plan">Export plan & note</button></div><div id="r-note-status" class="research-statusline" role="status"></div><p class="research-small">This research note has its own export. The existing study-notebook backup above does not contain it.</p></section>';
 }
 function advisor(){return head('A more critical advisor','The advisor turns a broad question into a testable contract, assigns bounded work and asks an independent verifier to challenge the result.','Separate proposal quality from acceptance. Freeze the evaluator, verify source-to-code consistency and distinguish mathematical, numerical and physical evidence.')+
  '<section class="research-panel"><h2>Use the protocol for the next research cycle</h2><div class="research-flow">'+[['1 · Contract','Action, state, units, sources, boundaries and claimed domain.'],['2 · Propose','A derivation or experiment with a falsifier and required artifact.'],['3 · Challenge','Independent implementation, exact limits and deliberate failure controls.'],['4 · Decide','Accept a bounded claim, reopen a failed gate or stop an unsupported path.']].map(([a,b])=>'<div><b>'+a+'</b><span>'+b+'</span></div>').join('')+'</div><div class="research-actions"><button class="research-primary" data-r-doc="advisor_pipeline.md">Read the full advisor guide</button><button data-r-download="advisor">Download protocol</button><a href="/advisor-and-research-guide.pdf" target="_blank" rel="noopener">Read the complete PDF guide</a><button data-r-doc="targeted_solver_prompt.md">Open the next solver specification</button></div><p class="research-note">This is a documented review workflow, not a continuously running agent service. The page does not create agents or spend model credits.</p></section>'+
  '<section class="research-panel"><h2>Panel roles and independence</h2>'+table(['Role','Owns','Cannot establish alone'],[['Advisor','Problem contract and scope decision','Physical truth by agreement'],['Theorist','Derivation, signs, limits','Correct implementation'],['Implementer','Runnable candidate and traceable results','Its own evaluator certification'],['Independent verifier','Different formulation and held-out checks','All continuum or experimental validity'],['Evidence critic','Versioned sources and counterexamples','Novel physics from authority'],['Integrator','Data-to-interface and release audit','A new science claim by visualization']])+'</section>'+
  '<section class="research-panel"><h2>What changed after the fresh review</h2><p>Two project skills now specify advisor decisions and numerical validation. Their forward exercise accepted a bounded response claim and rejected a false gauge-breaking inference. This was a nonblinded two-case exercise, not a general benchmark.</p><button data-r-doc="advisor_skill_forward_test.md">Inspect the skill exercise</button><ul><li>Added a source-to-code audit; it found an absent claimed fix.</li><li>Selected a new causal-response experiment with independent spinor checks.</li><li>Separated genuine quantum fluctuations from classical tangent sensitivity.</li><li>Preserved failed gates and stopped treating source count as coverage.</li></ul><p>Current-method sources include official OpenAI and Anthropic publications and original research; reading depth and reproduction limits appear in the source ledger.</p><div class="research-actions"><a href="#research/sources">Inspect the method sources</a><button data-r-doc="response_advisor_review.md">Read the physics review</button></div></section>';
 }
 function sourceRows(){const q=sourceQuery.trim().toLowerCase(),items=R.sources.filter(s=>(!sourceCategory||s.category===sourceCategory)&&(!q||JSON.stringify(s).toLowerCase().includes(q))),pages=Math.max(1,Math.ceil(items.length/15));sourcePage=Math.min(sourcePage,pages);return '<p class="research-small" role="status">'+items.length+' matching records · page '+sourcePage+' of '+pages+'</p>'+(items.length?items.slice((sourcePage-1)*15,sourcePage*15).map(s=>'<article class="research-source"><div class="research-tag">'+escape(s.id)+' · '+escape(s.category)+'</div><h3><a href="'+escape(/^https?:\/\//.test(s.url||'')?s.url:'#')+'" target="_blank" rel="noopener noreferrer">'+escape(s.title||'Untitled record')+'</a></h3><p>'+escape(Array.isArray(s.authors)?s.authors.join('; '):s.authors||s.publisher||'')+' · '+escape(s.date||s.year||'Date not specified')+'</p><p><strong>Reading depth:</strong> '+escape(s.readdepth||s.read_depth||s.reading_depth||s.access||'See linked record; full reading not certified.')+'</p>'+((s.limitation||s.limitations)?'<p><strong>Limit:</strong> '+escape(s.limitation||s.limitations)+'</p>':'')+'</article>').join(''):'<p class="research-note">No source matches. Clear the search or choose another category.</p>')+'<div class="research-actions"><button data-r-source-page="-1" '+(sourcePage===1?'disabled':'')+'>Previous</button><button data-r-source-page="1" '+(sourcePage===pages?'disabled':'')+'>Next</button></div>'}
 function sources(){return head('Read the evidence at its source','Search the exact papers, methods and documents used in this investigation. Reading a record is not the same as reproducing its result.','Versioned source ledger with inspected-section metadata, primary URLs and access/reproduction limits. Coverage is targeted, not an exhaustive census of all countries or literature.')+
  '<section class="research-panel"><div class="research-control"><label>Search sources<input id="r-source-search" type="search" value="'+escape(sourceQuery)+'" placeholder="Author, topic, paper, patent…"></label><label>Collection<select id="r-source-category"><option value="">All collections</option>'+[...new Set(R.sources.map(s=>s.category))].map(c=>'<option '+(sourceCategory===c?'selected':'')+'>'+escape(c)+'</option>').join('')+'</select></label><button class="research-button" data-r-clear-sources>Clear filters</button></div><div id="r-source-list">'+sourceRows()+'</div></section>';
 }
 function render(page='home'){
  if(!R)return '<section class="research-panel"><h1>Research data unavailable</h1><p>The research dataset did not load. Reload the page or continue with the study rooms.</p><a href="#study">Open Study</a></section>';
  if(!routes.some(r=>r[0]===page))return '<section class="research-panel"><h1>Research page not found</h1><p>The address does not identify a research view.</p><a href="#research">Return to the research home</a></section>';
  const pages={home,results,response,demonstrations,evidence,experiments:plan,advisor,sources};return '<div class="research-shell"><nav class="research-nav" aria-label="Research views">'+routes.map(([r,l])=>'<a href="#research/'+r+'" '+(r===page?'aria-current="page"':'')+'>'+l+'</a>').join('')+'</nav>'+pages[page]()+'</div>';
 }
 function currentPage(){return location.hash.split('/')[1]||'home'}
 function rerender(){const main=document.querySelector('#main');if(main){main.innerHTML=render(currentPage());afterRender()}}
 function afterRender(){if(!location.hash||location.hash.startsWith('#research')){document.title=(routes.find(r=>r[0]===currentPage())?.[1]||'Research')+' · Physics Observatory';if(currentPage()==='demonstrations'){calculate('mix');calculate('budget');calculate('detector')}}}
 function calculate(kind){let id=kind==='mix'?'#r-mix-result':kind==='budget'?'#r-budget-result':'#r-det-result';const out=document.querySelector(id);if(!out)return;try{
  if(kind==='mix'){const u=document.querySelector('#r-mix-u').value,v=document.querySelector('#r-mix-v').value,p=mixing(u,v),points=Array.from({length:101},(_,i)=>[i/100,mixing(Number(u)*i/100,Number(v)*i/100)]);out.innerHTML='<p>Conversion probability: <strong>'+fmt(p*100)+'%</strong></p>'+chart([{name:'Specified mismatch',points},{name:'Zero mismatch',points:Array.from({length:101},(_,i)=>[i/100,mixing(Number(u)*i/100,0)])}],{title:'Two-mode conversion along the path',xLabel:'Fraction of path length',yLabel:'Probability P'});}
  if(kind==='budget'){const z=budget(document.querySelector('#r-budget-x').value,document.querySelector('#r-budget-b').value);out.innerHTML='<p>Electromagnetic source scale κρ / mₑ²: <strong>'+escape(z.toExponential(5))+'</strong></p><p>'+(z<1?'Below unity: these fields alone do not supply an electron-scale source budget.':'This algebraic source budget reaches unity; no controlled QED or gravitational solution is implied.')+'</p><div class="research-eq">κρEM / mₑ² = (4πGmₑ² / e²) (x² + b²)</div>';}
  if(kind==='detector'){const ns=document.querySelector('#r-det-ns').value,lo=document.querySelector('#r-det-lo').value,z=detector(ns,lo);out.innerHTML='<p>Signal-to-noise ratio: <strong>'+fmt(z)+'</strong></p><p>Strong-reference limit: '+fmt(2*Math.sqrt(Number(ns)))+'</p>'+chart([{name:'Coherent SNR',points:Array.from({length:81},(_,i)=>{const exp=-2+i/10;return [exp,detector(ns,10**exp)]})}],{title:'Reference power and finite SNR',xLabel:'log₁₀(reference photons)',yLabel:'SNR'});}
 }catch(e){out.innerHTML='<p class="research-error" role="alert">'+escape(e.message)+'</p>'}}
 function modal(title,html,opener){const d=document.querySelector('#research-dialog');if(!d)return;lastOpener=opener||document.activeElement;document.querySelector('#research-title').textContent=title;document.querySelector('#research-body').innerHTML=html;if(!d.open)d.showModal();d.querySelector('[data-r-close]')?.focus()}
 function info(name,opener){const content={
  baseline:['What the recorded run means','<p>A massive Dirac field is quantized in flat homogeneous spacetime. A smooth external current supplies energy for 0 &lt; s &lt; 4. The electric field then responds to the computed expectation-value current. The magnetic field stays fixed.</p><p>No metric evolution, collision term or full quantum photon fluctuations are included.</p>'+table(['Parameter','Value'],Object.entries(R.baseline.parameters))+'<p class="research-small">Recorded solver SHA-256: '+escape(R.meta.source_hash)+'</p><p>'+links(['C01','C02','C03'])+'</p>'],
  matching:['Subtract divergences; retain the physical finite response','<p>The current and energy counterterms come from the same expansion. Subtracting the whole magnetic adiabatic response removes a real finite susceptibility unless it is restored by physical charge matching.</p><div class="research-eq">Z = 1 + χB − e²C; x′ = [F − e²(S + Dx²)] / Z<br>W = Zx²/2 + e²U; W′ = xF</div><p>A consistently wrong finite matching can still conserve its own energy. The weak-source comparison supplies a separate physical check.</p><p>'+links(['C01','C02','N02'])+'</p>'],
  claims:['Unusual claims need complete accounting','<p>The project tested specific mathematical inferences: stationary action does not imply d(Ut)=0; isolated internal Coulomb forces cancel; stored cavity energy saturates; a coherent local oscillator does not create unlimited noise-free gain.</p><p>These tests do not reconstruct every apparatus or establish the cause of an unexamined measurement. Patent or government provenance alone is not physical validation.</p><p>'+links(['E15','E08','E09','E13'])+'</p>']};const c=content[name];if(c)modal(c[0],c[1],opener)}
 function front(id,opener){const f=fronts.find(f=>f.id===id);if(f)modal(f.name,'<p>'+escape(f.simple)+'</p><div class="research-eq">'+escape(f.equation)+'</div><p>'+escape(f.technical)+'</p><h3>Required next evidence</h3><p>'+escape(f.gap)+'</p><p>'+escape(f.test)+'</p><h3>Primary sources</h3><p>'+links(f.sources)+'</p>',opener)}
 function download(filename,text,type='text/plain'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 function exportData(kind){if(kind==='response-csv'){const m=responseRecord()?.base?.macro;if(m)download(responseCase+'-'+responseMetric+'.csv','s,'+responseMetric+'\n'+m.s.map((t,i)=>[t,m[responseMetric][i]].join(',')).join('\n'),'text/csv');return}if(kind==='baseline'){download('recorded-'+metric+'.csv','s,'+metric+'\n'+baselineSeries(metric).map(p=>p.join(',')).join('\n'),'text/csv');return}if(kind==='response'){if(!R.response){modal('No response data','<p>No response dataset is included in this snapshot.</p>');return}download('response-records.json',JSON.stringify(R.response,null,2),'application/json');return}if(kind==='advisor'){download('advisor-pipeline.md',R.documents['advisor_pipeline.md']||'Protocol unavailable in this snapshot.');return}if(kind==='plan'){let note=document.querySelector('#r-note')?.value||'';download('research-plan.json',JSON.stringify({snapshot:R.meta.date,experiments:experiments.map(e=>({id:e[0],title:e[1],status:e[2],test:e[3],rejection:e[4],dependencies:e[5]})),note},null,2),'application/json')}}
 document.addEventListener('click',e=>{const b=e.target.closest('[data-r-mode],[data-r-info],[data-r-front],[data-r-close],[data-r-calc],[data-r-download],[data-r-doc],[data-r-save-note],[data-r-source-page],[data-r-clear-sources]');if(!b)return;
  if(b.hasAttribute('data-r-mode')){technical=b.dataset.rMode==='technical';try{localStorage.setItem('observatory-explanation-mode',technical?'technical':'plain')}catch{}rerender();document.querySelector('[data-r-mode="'+(technical?'technical':'plain')+'"]')?.focus()}
  if(b.dataset.rInfo)info(b.dataset.rInfo,b);if(b.dataset.rFront)front(b.dataset.rFront,b);if(b.hasAttribute('data-r-close'))document.querySelector('#research-dialog')?.close();if(b.dataset.rCalc)calculate(b.dataset.rCalc);if(b.dataset.rDownload)exportData(b.dataset.rDownload);
  if(b.dataset.rDoc){const text=R.documents[b.dataset.rDoc];modal(b.dataset.rDoc.replace(/_/g,' ').replace('.md',''),text?'<div class="research-doc">'+escape(text)+'</div>':'<p>This document is not included in the current snapshot.</p>',b)}
  if(b.hasAttribute('data-r-save-note')){const out=document.querySelector('#r-note-status');try{localStorage.setItem('observatory-research-note',document.querySelector('#r-note').value);out.textContent='Saved in this browser.'}catch{out.textContent='Browser storage is unavailable. Export your plan and note to keep them.'}}
  if(b.dataset.rSourcePage){sourcePage+=Number(b.dataset.rSourcePage);document.querySelector('#r-source-list').innerHTML=sourceRows();document.querySelector('#r-source-search')?.focus()}
  if(b.hasAttribute('data-r-clear-sources')){sourceQuery='';sourceCategory='';sourcePage=1;rerender();document.querySelector('#r-source-search')?.focus()}
 });
 document.addEventListener('change',e=>{if(e.target.id==='r-response-case'){responseCase=e.target.value;document.querySelector('#r-response-view').innerHTML=responseContent()}if(e.target.id==='r-response-metric'){responseMetric=e.target.value;document.querySelector('#r-response-chart').innerHTML=responsePlot();document.querySelector('#r-response-table').innerHTML=responseTable()}if(e.target.id==='r-metric'){metric=e.target.value;document.querySelector('#r-main-chart').innerHTML=baselineChart(metric);document.querySelector('#r-data-table').innerHTML=metricTable()}if(e.target.id==='r-source-category'){sourceCategory=e.target.value;sourcePage=1;document.querySelector('#r-source-list').innerHTML=sourceRows()}});
 document.addEventListener('input',e=>{if(e.target.id==='r-source-search'){sourceQuery=e.target.value;sourcePage=1;document.querySelector('#r-source-list').innerHTML=sourceRows()}});
 window.addEventListener('DOMContentLoaded',()=>{const d=document.querySelector('#research-dialog');if(d){d.addEventListener('close',()=>{if(lastOpener?.isConnected)lastOpener.focus();else document.querySelector('#main')?.focus()});d.addEventListener('click',e=>{if(e.target===d)d.close()})}});
 window.addEventListener('hashchange',()=>{const d=document.querySelector('#research-dialog');if(d?.open)d.close()});
 window.ResearchObservatory={render,afterRender,mixing,budget,detector,chart,baselineSeries};
})();
